322		where the answer summation is over $g \in \mathrm{ideg}_{d,m}(\F_q)$. The independently quantified scale $\delta_P^{\mathrm{ann}}$ includes the additional point-measurement error in \eqref{eq:qld-sg-cons2}. Furthermore, all symmetric equivalents of these approximations also hold (Definition~\ref{def:symmetric-equivalents}).
323	\end{lemma}
324	\begin{proof}
325		\uses{lem:qld-4-7, fact:agreement, fact:add-a-proj, def:bracket, lem:qld-comm-cons}
326		The point-consistency conclusion of Lemma~\ref{lem:qld-4-7} states that, on average over $u \in \F_q^m$,
327		\[
328			\bra{\hat\psi} \sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point}, W), u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \ket{\hat\psi} \geq 1 - \delta_G\;,
329		\]
330		which says exactly that the operator on the left-hand side of \eqref{eq:qld-sg-cons} is $\delta_G$-consistent with $\Id$; Lemma~\ref{fact:agreement} and the universal-factor enlargement give the $\approx_{\delta_P}$ statement \eqref{eq:qld-sg-cons}. For \eqref{eq:qld-sg-cons2}, the same consistency, written with the coarse-graining $\hat{S}^W_{[g(u)=a]} = \sum_{g : g(u) = a} \hat{S}^W_g$ as $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G)} (\hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{B}\mathrm{A}''}$ with answer summation over $a \in \F_q$, is left-multiplied by $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'}$ using Lemma~\ref{fact:add-a-proj}; moving $\hat{M}^{(\mathrm{Point}, W), u}_a$ from registers $\mathrm{B}\mathrm{A}''$ to $\mathrm{A}\mathrm{A}'$ costs a further $\eps$ by Cauchy--Schwarz together with the self-consistency of the $\hat{M}^{(\mathrm{Point}, W), u}_a$ (Lemma~\ref{lem:qld-comm-cons}), giving
331		\[
332			(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G + \eps)} (\hat{S}^W_{[g(u)=a]} \cdot \hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{A}\mathrm{A}'}\;.
333		\]
334		Expanding
335		\[
336			\E_u \sum_g \bigl\| (\hat{S}^W_{g} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)}))_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi} \bigr\|^2
337			= \E_u \sum_a \bra{\hat\psi} \bigl((\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a}) \cdot \hat{S}^W_{[g(u)=a]} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a})\bigr)_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi}
338		\]
339		and bounding the right-hand side by $O(\delta_G + \eps)$ using the two approximations above yields \eqref{eq:qld-sg-cons2} at scale $\delta_P$. The symmetric equivalents follow by the same argument with the register bipartitions interchanged.
340	\end{proof}
